@namespace sv_ad3776768dbd4d51866ec673acef891b.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul class="settings-nav">
        @foreach (var section in Sections)
        {
            <li class="settings-nav-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="settings-nav-icon">@GetIcon(section)</span>
                <span class="settings-nav-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_ad3776768dbd4d51866ec673acef891b.Components.Pages.Settings

<div class="settings-section">
    <h2>Profile Settings</h2>

    <div class="profile-avatar-area">
        <div class="avatar-preview">
            @if (!string.IsNullOrWhiteSpace(DisplayName))
            {
                <img src="@AvatarUrl" alt="Avatar" class="avatar-image" />
            }
            else
            {
                <div class="avatar-placeholder">No Avatar</div>
            }
        </div>
        <div class="avatar-url-display">
            <label>Avatar URL</label>
            <span class="avatar-url-text">@AvatarUrl</span>
        </div>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" class="form-control" @bind="DisplayName" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" class="form-control" @bind="Email" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" class="form-control" rows="4" @bind="Bio"></textarea>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="HandleSave">Save Changes</button>
        <button class="btn btn-secondary" @onclick="HandleDiscard">Discard Changes</button>
    </div>

    @if (ShowSuccessMessage)
    {
        <div class="toast-message toast-success">Profile saved successfully!</div>
    }
</div>

@code {
    [Parameter] public string DisplayName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Bio { get; set; } = "";
    [Parameter] public string AvatarUrl { get; set; } = "";
    [Parameter] public EventCallback<(string DisplayName, string Email, string Bio)> OnSave { get; set; }
    [Parameter] public EventCallback OnDiscard { get; set; }

    private bool ShowSuccessMessage;

    private async Task HandleSave()
    {
        await OnSave.InvokeAsync((DisplayName, Email, Bio));
        ShowSuccessMessage = true;
        _ = DismissToastAfterDelay();
    }

    private async Task HandleDiscard()
    {
        await OnDiscard.InvokeAsync();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccessMessage = false;
        StateHasChanged();
    }
}

@namespace sv_ad3776768dbd4d51866ec673acef891b.Components.Pages.Settings

<div class="settings-section">
    <h2>Notification Preferences</h2>

    <div class="toggle-group">
        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" @bind="EmailNotifications" />
                <span class="toggle-switch"></span>
                Email Notifications
            </label>
        </div>

        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" @bind="PushNotifications" />
                <span class="toggle-switch"></span>
                Push Notifications
            </label>
        </div>

        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" @bind="WeeklyDigest" />
                <span class="toggle-switch"></span>
                Weekly Digest
            </label>
        </div>
    </div>

    <div class="channel-list">
        <h3>Muted Channels</h3>
        @if (Channels.Count > 0)
        {
            @foreach (var channel in Channels)
            {
                <div class="channel-item">
                    <label>
                        <input type="checkbox"
                               checked="@MutedChannels.Contains(channel)"
                               @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                        @channel
                    </label>
                </div>
            }
        }
        else
        {
            <p class="text-muted">No channels available.</p>
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="HandleSave">Save Preferences</button>
    </div>

    @if (ShowSuccessMessage)
    {
        <div class="toast-message toast-success">Preferences saved successfully!</div>
    }
</div>

@code {
    [Parameter] public bool EmailNotifications { get; set; }
    [Parameter] public bool PushNotifications { get; set; }
    [Parameter] public bool WeeklyDigest { get; set; }
    [Parameter] public List<string> MutedChannels { get; set; } = new();
    [Parameter] public List<string> Channels { get; set; } = new();
    [Parameter] public EventCallback<(bool Email, bool Push, bool Digest, List<string> Muted)> OnSave { get; set; }

    private bool ShowSuccessMessage;

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!isMuted)
            MutedChannels.Remove(channel);
    }

    private async Task HandleSave()
    {
        await OnSave.InvokeAsync((EmailNotifications, PushNotifications, WeeklyDigest, MutedChannels));
        ShowSuccessMessage = true;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccessMessage = false;
        StateHasChanged();
    }
}

@namespace sv_ad3776768dbd4d51866ec673acef891b.Components.Pages.Settings

<div class="expandable-panel">
    <button class="panel-header" @onclick="ToggleExpanded">
        <span>Change Password</span>
        <span class="panel-toggle">@(IsExpanded ? "▼" : "▶")</span>
    </button>

    @if (IsExpanded)
    {
        <div class="panel-body">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" class="form-control" @bind="CurrentPassword" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" class="form-control" @bind="NewPassword" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" class="form-control" @bind="ConfirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(ErrorMessage))
            {
                <div class="toast-message toast-error">@ErrorMessage</div>
            }

            @if (ShowSuccess)
            {
                <div class="toast-message toast-success">Password updated successfully!</div>
            }

            <button class="btn btn-primary" @onclick="HandleUpdatePassword" disabled="@IsSubmitting">
                @(IsSubmitting ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool IsExpanded;
    private string CurrentPassword = "";
    private string NewPassword = "";
    private string ConfirmPassword = "";
    private string? ErrorMessage;
    private bool ShowSuccess;
    private bool IsSubmitting;

    private void ToggleExpanded() => IsExpanded = !IsExpanded;

    private async Task HandleUpdatePassword()
    {
        ErrorMessage = null;
        ShowSuccess = false;

        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            ErrorMessage = "All password fields are required.";
            return;
        }

        if (NewPassword != ConfirmPassword)
        {
            ErrorMessage = "New password and confirmation do not match.";
            return;
        }

        IsSubmitting = true;
        try
        {
            await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
            ShowSuccess = true;
            CurrentPassword = "";
            NewPassword = "";
            ConfirmPassword = "";
        }
        catch (Exception ex)
        {
            ErrorMessage = ex.Message;
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

@namespace sv_ad3776768dbd4d51866ec673acef891b.Components.Pages.Settings

<div class="sessions-section">
    <h3>Active Sessions</h3>

    @if (Sessions.Count == 0)
    {
        <p class="text-muted">No active sessions.</p>
    }
    else
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-danger btn-sm"
                                        @onclick="() => PromptRevoke(session.Id)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="badge badge-current">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }

    @if (ShowConfirmDialog)
    {
        <div class="confirm-dialog-overlay">
            <div class="confirm-dialog">
                <p>Are you sure you want to revoke this session?</p>
                <div class="confirm-dialog-actions">
                    <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke Session</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private bool ShowConfirmDialog;
    private string? PendingRevokeId;

    private void PromptRevoke(string sessionId)
    {
        PendingRevokeId = sessionId;
        ShowConfirmDialog = true;
    }

    private async Task ConfirmRevoke()
    {
        if (PendingRevokeId is not null)
        {
            await OnRevoke.InvokeAsync(PendingRevokeId);
        }
        ShowConfirmDialog = false;
        PendingRevokeId = null;
    }

    private void CancelRevoke()
    {
        ShowConfirmDialog = false;
        PendingRevokeId = null;
    }

    public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
}

@namespace sv_ad3776768dbd4d51866ec673acef891b.Components.Pages.Settings

<div class="settings-section">
    <h2>Security Settings</h2>

    <ChangePasswordPanel OnChangePassword="OnChangePassword" />

    <div class="two-factor-section">
        <h3>Two-Factor Authentication</h3>
        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" checked="@TwoFactorEnabled" disabled />
                <span class="toggle-switch"></span>
                Two-Factor Authentication
            </label>
            <span class="status-indicator @(TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                @(TwoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>
        @if (LastPasswordChange.HasValue)
        {
            <p class="text-muted">Last password change: @LastPasswordChange.Value.ToString("f")</p>
        }
    </div>

    <ActiveSessionsTable Sessions="@Sessions"
                         CurrentSessionId="@CurrentSessionId"
                         OnRevoke="OnRevokeSession" />
</div>

@code {
    [Parameter] public bool TwoFactorEnabled { get; set; }
    [Parameter] public DateTime? LastPasswordChange { get; set; }
    [Parameter] public List<ActiveSessionsTable.ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
}

@namespace sv_ad3776768dbd4d51866ec673acef891b.Components.Pages.Settings

<div class="settings-section">
    <h2>Appearance Settings</h2>

    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            <label class="radio-label">
                <input type="radio" name="theme" value="Light"
                       checked="@(Theme == "Light")"
                       @onchange="@(() => Theme = "Light")" />
                Light
            </label>
            <label class="radio-label">
