@namespace sv_ad3776768dbd4d51866ec673acef891b.Components.Pages.Settings

<div class="sessions-section">
    <h3>Active Sessions</h3>

    @if (Sessions.Count == 0)
    {
        <p class="text-muted">No active sessions.</p>
    }
    else
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-danger btn-sm"
                                        @onclick="() => PromptRevoke(session.Id)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="badge badge-current">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }

    @if (ShowConfirmDialog)
    {
        <div class="confirm-dialog-overlay">
            <div class="confirm-dialog">
                <p>Are you sure you want to revoke this session?</p>
                <div class="confirm-dialog-actions">
                    <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke Session</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private bool ShowConfirmDialog;
    private string? PendingRevokeId;

    private void PromptRevoke(string sessionId)
    {
        PendingRevokeId = sessionId;
        ShowConfirmDialog = true;
    }

    private async Task ConfirmRevoke()
    {
        if (PendingRevokeId is not null)
        {
            await OnRevoke.InvokeAsync(PendingRevokeId);
        }
        ShowConfirmDialog = false;
        PendingRevokeId = null;
    }

    private void CancelRevoke()
    {
        ShowConfirmDialog = false;
        PendingRevokeId = null;
    }

    public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
}

