@namespace sv_ad3776768dbd4d51866ec673acef891b.Components.Pages.Settings

<div class="settings-section">
    <h2>Appearance Settings</h2>

    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            <label class="radio-label">
                <input type="radio" name="theme" value="Light"
                       checked="@(Theme == "Light")"
                       @onchange="@(() => Theme = "Light")" />
                Light
            </label>
            <label class="radio-label">
                <input type="radio" name="theme" value="Dark"
                       checked="@(Theme == "Dark")"
                       @onchange="@(() => Theme = "Dark")" />
                Dark
            </label>
            <label class="radio-label">
                <input type="radio" name="theme" value="System"
                       checked="@(Theme == "System")"
                       @onchange="@(() => Theme = "System")" />
                System
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            <label class="radio-label">
                <input type="radio" name="fontSize" value="Small"
                       checked="@(FontSize == "Small")"
                       @onchange="@(() => FontSize = "Small")" />
                Small
            </label>
            <label class="radio-label">
                <input type="radio" name="fontSize" value="Medium"
                       checked="@(FontSize == "Medium")"
                       @onchange="@(() => FontSize = "Medium")" />
                Medium
            </label>
            <label class="radio-label">
                <input type="radio" name="fontSize" value="Large"
                       checked="@(FontSize == "Large")"
                       @onchange="@(() => FontSize = "Large")" />
                Large
            </label>
        </div>
    </div>

    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" class="form-control" @bind="Language">
            <option value="en">English</option>
            <option value="es">Spanish</option>
            <option value="fr">French</option>
            <option value="de">German</option>
            <option value="ja">Japanese</option>
            <option value="zh">Chinese</option>
        </select>
    </div>

    <div class="toggle-item">
        <label class="toggle-label">
            <input type="checkbox" @bind="CompactMode" />
            <span class="toggle-switch"></span>
            Compact Mode
        </label>
    </div>

    <div class="appearance-preview" style="@GetPreviewStyle()">
        <h4>Live Preview</h4>
        <p>This is how your content will look with the selected settings.</p>
        <div class="preview-card">
            <strong>Sample Card</strong>
            <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</p>
            <button class="btn btn-primary btn-preview">Sample Button</button>
        </div>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="HandleSave">Save</button>
    </div>

    @if (ShowSuccessMessage)
    {
        <div class="toast-message toast-success">Appearance settings saved!</div>
    }
</div>

@code {
    [Parameter] public string Theme { get; set; } = "System";
    [Parameter] public string FontSize { get; set; } = "Medium";
    [Parameter] public string Language { get; set; } = "en";
    [Parameter] public bool CompactMode { get; set; }
    [Parameter] public EventCallback<(string Theme, string FontSize, string Language, bool CompactMode)> OnSave { get; set; }

    private bool ShowSuccessMessage;

    private string GetPreviewStyle()
    {
        var bgColor = Theme switch
        {
            "Dark" => "#1e1e2e",
            "Light" => "#ffffff",
            _ => "#f5f5f5"
        };
        var textColor = Theme == "Dark" ? "#e0e0e0" : "#333333";
        var fontSize = FontSize switch
        {
            "Small" => "12px",
            "Large" => "18px",
            _ => "14px"
        };
        var padding = CompactMode ? "8px" : "16px";

        return $"background-color: {bgColor}; color: {textColor}; font-size: {fontSize}; padding: {padding}; border-radius: 8px; margin-top: 16px;";
    }

    private async Task HandleSave()
    {
        await OnSave.InvokeAsync((Theme, FontSize, Language, CompactMode));
        ShowSuccessMessage = true;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccessMessage = false;
        StateHasChanged();
    }
}

