@page "/settings"
@namespace sv_ad3776768dbd4d51866ec673acef891b.Components.Pages.Settings
@rendermode InteractiveServer
@using sv_ad3776768dbd4d51866ec673acef891b.Components.Pages.Settings
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="SetActiveSection" />

    <div class="settings-content">
        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection DisplayName="@profileDisplayName"
                                Email="@profileEmail"
                                Bio="@profileBio"
                                AvatarUrl="@profileAvatarUrl"
                                OnSave="SaveProfile"
                                OnDiscard="DiscardProfileChanges" />
                break;

            case "Notifications":
                <NotificationsSection EmailNotifications="@notifEmail"
                                      PushNotifications="@notifPush"
                                      WeeklyDigest="@notifDigest"
                                      MutedChannels="@mutedChannels"
                                      Channels="@allChannels"
                                      OnSave="SaveNotifications" />
                break;

            case "Security":
                <SecuritySection TwoFactorEnabled="@twoFactorEnabled"
                                 LastPasswordChange="@lastPasswordChange"
                                 Sessions="@activeSessions"
                                 CurrentSessionId="@currentSessionId"
                                 OnChangePassword="HandleChangePassword"
                                 OnRevokeSession="HandleRevokeSession" />
                break;

            case "Appearance":
                <AppearanceSection Theme="@appearanceTheme"
                                   FontSize="@appearanceFontSize"
                                   Language="@appearanceLanguage"
                                   CompactMode="@appearanceCompact"
                                   OnSave="SaveAppearance" />
                break;
        }
    </div>
</div>

@code {
    private string activeSection = "Profile";

    // Profile state
    private string profileDisplayName = "";
    private string profileEmail = "";
    private string profileBio = "";
    private string profileAvatarUrl = "";
    private UserProfile? savedProfile;

    // Notifications state
    private bool notifEmail;
    private bool notifPush;
    private bool notifDigest;
    private List<string> mutedChannels = new();
    private List<string> allChannels = new() { "general", "announcements", "random", "dev", "design" };

    // Security state
    private bool twoFactorEnabled;
    private DateTime? lastPasswordChange;
    private List<ActiveSessionsTable.ActiveSession> activeSessions = new();
    private string currentSessionId = "";

    // Appearance state
    private string appearanceTheme = "System";
    private string appearanceFontSize = "Medium";
    private string appearanceLanguage = "en";
    private bool appearanceCompact;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
        await LoadNotificationsAsync();
        await LoadSecurityAsync();
        await LoadAppearanceAsync();
    }

    private void SetActiveSection(string section)
    {
        activeSection = section;
    }

    // Profile
    private async Task LoadProfileAsync()
    {
        var profile = await SettingsService.GetProfileAsync();
        savedProfile = profile;
        profileDisplayName = profile.DisplayName;
        profileEmail = profile.Email;
        profileBio = profile.Bio;
        profileAvatarUrl = profile.AvatarUrl;
    }

    private async Task SaveProfile((string DisplayName, string Email, string Bio) data)
    {
        var updated = new UserProfile(data.DisplayName, data.Email, profileAvatarUrl, data.Bio);
        await SettingsService.SaveProfileAsync(updated);
        savedProfile = updated;
        profileDisplayName = updated.DisplayName;
        profileEmail = updated.Email;
        profileBio = updated.Bio;
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile is not null)
        {
            profileDisplayName = savedProfile.DisplayName;
            profileEmail = savedProfile.Email;
            profileBio = savedProfile.Bio;
            profileAvatarUrl = savedProfile.AvatarUrl;
        }
    }

    // Notifications
    private async Task LoadNotificationsAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        notifEmail = prefs.EmailNotifications;
        notifPush = prefs.PushNotifications;
        notifDigest = prefs.WeeklyDigest;
        mutedChannels = new List<string>(prefs.MutedChannels);
    }

    private async Task SaveNotifications((bool Email, bool Push, bool Digest, List<string> Muted) data)
    {
        var prefs = new NotificationPrefs(data.Email, data.Push, data.Digest, data.Muted);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        notifEmail = data.Email;
        notifPush = data.Push;
        notifDigest = data.Digest;
        mutedChannels = new List<string>(data.Muted);
    }

    // Security
    private async Task LoadSecurityAsync()
    {
        var security = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = security.TwoFactorEnabled;
        lastPasswordChange = security.LastPasswordChange;
        activeSessions = security.Sessions
            .Select(s => new ActiveSessionsTable.ActiveSession(s.Id, s.Device, s.Location, s.LastActive))
            .ToList();
        if (security.Sessions.Count > 0)
            currentSessionId = security.Sessions[0].Id;
    }

    private async Task HandleChangePassword((string Current, string New) data)
    {
        await SettingsService.ChangePasswordAsync(data.Current, data.New);
        lastPasswordChange = DateTime.UtcNow;
    }

    private async Task HandleRevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        activeSessions.RemoveAll(s => s.Id == sessionId);
    }

    // Appearance
    private async Task LoadAppearanceAsync()
    {
        var appearance = await SettingsService.GetAppearanceAsync();
        appearanceTheme = appearance.Theme;
        appearanceFontSize = appearance.FontSize;
        appearanceLanguage = appearance.Language;
        appearanceCompact = appearance.CompactMode;
    }

    private async Task SaveAppearance((string Theme, string FontSize, string Language, bool CompactMode) data)
    {
        var settings = new AppearanceSettings(data.Theme, data.FontSize, data.Language, data.CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        appearanceTheme = data.Theme;
        appearanceFontSize = data.FontSize;
        appearanceLanguage = data.Language;
        appearanceCompact = data.CompactMode;
    }
}

.settings-dashboard {
    display: flex;
    min-height: 100vh;
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background-color: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 24px 0;
    flex-shrink: 0;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 24px;
    cursor: pointer;
    transition: background-color 0.2s, border-left 0.2s;
    border-left: 3px solid transparent;
    font-size: 14px;
    color: #555;
}

.settings-nav-item:hover {
    background-color: #e9ecef;
}

.settings-nav-item.active {
    background-color: #e3f2fd;
    border-left-color: #1976d2;
    color: #1976d2;
    font-weight: 600;
}

.settings-nav-icon {
    font-size: 18px;
}

/* Content area */
.settings-content {
    flex: 1;
    padding: 32px 40px;
    max-width: 800px;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 24px;
    font-size: 24px;
    font-weight: 600;
    color: #212121;
}

.settings-section h3 {
    margin-top: 24px;
    margin-bottom: 12px;
    font-size: 16px;
    font-weight: 600;
    color: #424242;
}

/* Forms */
.form-group {
    margin-bottom: 20px;
}

.form-group label {
    display: block;
    margin-bottom: 6px;
    font-size: 14px;
    font-weight: 500;
    color: #555;
}

.form-control {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 14px;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #1976d2;
    box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.1);
}

textarea.form-control {
    resize: vertical;
}

/* Buttons */
.btn {
    padding: 10px 20px;
    border: none;
    border-radius: 6px;
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.2s, opacity 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background-color: #1976d2;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background-color: #1565c0;
}

.btn-secondary {
    background-color: #e0e0e0;
    color: #424242;
}

.btn-secondary:hover:not(:disabled) {
    background-color: #bdbdbd;
}

.btn-danger {
    background-color: #d32f2f;
    color: white;
}

.btn-danger:hover:not(:disabled) {
    background-color: #c62828;
}

.btn-sm {
    padding: 6px 12px;
    font-size: 12px;
}

.form-actions {
    display: flex;
    gap: 12px;
    margin-top: 24px;
}

/* Toast messages */
.toast-message {
    margin-top: 16px;
    padding: 12px 16px;
    border-radius: 6px;
    font-size: 14px;
    animation: fadeIn 0.3s ease;
}

.toast-success {
    background-color: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.toast-error {
    background-color: #ffebee;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-8px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Profile section */
.profile-avatar-area {
    display: flex;
    align-items: center;
    gap: 20px;
    margin-bottom: 24px;
    padding: 16px;
    background-color: #f5f5f5;
    border-radius: 8px;
}

.avatar-preview {
