}

.avatar-placeholder {
    font-size: 12px;
    color: #999;
}

.avatar-url-display {
    flex: 1;
}

.avatar-url-display label {
    font-size: 12px;
    color: #777;
    margin-bottom: 4px;
    display: block;
}

.avatar-url-text {
    font-size: 13px;
    color: #555;
