.toggle-group {
    margin-bottom: 24px;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 10px;
    cursor: pointer;
    font-size: 14px;
}

.toggle-label input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #1976d2;
}

/* Channel list */
.channel-list {
    margin-top: 24px;
    padding: 16px;
    background-color: #fafafa;
    border-radius: 8px;
}

.channel-item {
    padding: 8px 0;
    border-bottom: 1px solid #f0f0f0;
}

.channel-item:last-child {
    border-bottom: none;
}

.channel-item label {
    display: flex;
    align-items: center;
    gap: 10px;
    cursor: pointer;
    font-size: 14px;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    margin-bottom: 24px;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 16px 20px;
    background-color: #fafafa;
    border: none;
    cursor: pointer;
    font-size: 15px;
    font-weight: 500;
    color: #333;
    transition: background-color 0.2s;
}

.panel-header:hover {
    background-color: #f0f0f0;
}

.panel-toggle {
    font-size: 12px;
    color: #777;
}

.panel-body {
    padding: 20px;
    border-top: 1px solid #e0e0e0;
}

/* Two-factor section */
.two-factor-section {
    margin-bottom: 24px;
}

.status-indicator {
    font-size: 12px;
    font-weight: 600;
    padding: 4px 8px;
    border-radius: 4px;
}

.status-enabled {
    background-color: #e8f5e9;
    color: #2e7d32;
}

.status-disabled {
    background-color: #fff3e0;
    color: #e65100;
}

/* Sessions table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 12px;
}

.sessions-table th,
.sessions-table td {
    text-align: left;
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    font-size: 14px;
}

.sessions-table th {
    background-color: #f5f5f5;
    font-weight: 600;
    color: #555;
}

.badge-current {
    font-size: 11px;
    padding: 4px 8px;
    background-color: #e3f2fd;
    color: #1976d2;
    border-radius: 4px;
    font-weight: 600;
}

/* Confirmation dialog */
.confirm-dialog-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.confirm-dialog {
    background: white;
    padding: 24px;
    border-radius: 12px;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
    max-width: 400px;
    width: 90%;
}

.confirm-dialog p {
    margin: 0 0 20px;
    font-size: 15px;
    color: #333;
}

.confirm-dialog-actions {
    display: flex;
    gap: 12px;
    justify-content: flex-end;
}

/* Appearance section */
.radio-group {
    display: flex;
    gap: 20px;
    margin-top: 4px;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 6px;
    cursor: pointer;
    font-size: 14px;
}

.radio-label input[type="radio"] {
    accent-color: #1976d2;
}

.appearance-preview {
    border: 1px solid #e0e0e0;
    margin-top: 24px;
}

.appearance-preview h4 {
    margin-top: 0;
    margin-bottom: 8px;
}

.appearance-preview p {
    margin: 0 0 12px;
}

.preview-card {
    padding: 12px;
    border: 1px solid rgba(128, 128, 128, 0.3);
    border-radius: 6px;
    margin-top: 8px;
}

.preview-card p {
    font-size: inherit;
    opacity: 0.8;
}

.btn-preview {
    margin-top: 8px;
}

/* Utilities */
.text-muted {
    color: #888;
    font-size: 13px;
}

select.form-control {
    appearance: auto;
}
