.settings-content {
    flex: 1;
    padding: 32px 40px;
    max-width: 800px;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 24px;
    font-size: 24px;
    font-weight: 600;
    color: #212121;
}

.settings-section h3 {
    margin-top: 24px;
    margin-bottom: 12px;
    font-size: 16px;
    font-weight: 600;
    color: #424242;
}

