.toast-message {
    margin-top: 16px;
    padding: 12px 16px;
    border-radius: 6px;
    font-size: 14px;
    animation: fadeIn 0.3s ease;
}

.toast-success {
    background-color: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.toast-error {
    background-color: #ffebee;
    color: #c62828;
    border: 1px solid #ef9a9a;
